SELECT 19553 AS org, b.role AS role, b.organization_id AS other, o.name AS oname, o.country AS ocountry, count(DISTINCT q.tid) AS tenders FROM (SELECT DISTINCT p.tender_id AS tid, p.seq AS sq FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 19553 AND p.seq = t.current_seq AND p.role IN ('buyer', 'Procedure-Buyer') LIMIT 200) q CROSS JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq CROSS JOIN organizations o ON o.id = b.organization_id WHERE b.organization_id <> 19553 GROUP BY b.role, b.organization_id UNION ALL SELECT 19553 AS org, 'SOURCE' AS role, NULL AS other, t.source AS oname, t.kind AS ocountry, count(*) AS tenders FROM (SELECT DISTINCT p.tender_id AS tid, p.seq AS sq FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 19553 AND p.seq = t.current_seq AND p.role IN ('buyer', 'Procedure-Buyer') LIMIT 200) q CROSS JOIN tenders t ON t.id = q.tid GROUP BY t.source, t.kind UNION ALL SELECT 2997642 AS org, b.role AS role, b.organization_id AS other, o.name AS oname, o.country AS ocountry, count(DISTINCT q.tid) AS tenders FROM (SELECT DISTINCT p.tender_id AS tid, p.seq AS sq FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 2997642 AND p.seq = t.current_seq AND p.role IN ('buyer', 'Procedure-Buyer') LIMIT 200) q CROSS JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq CROSS JOIN organizations o ON o.id = b.organization_id WHERE b.organization_id <> 2997642 GROUP BY b.role, b.organization_id UNION ALL SELECT 2997642 AS org, 'SOURCE' AS role, NULL AS other, t.source AS oname, t.kind AS ocountry, count(*) AS tenders FROM (SELECT DISTINCT p.tender_id AS tid, p.seq AS sq FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 2997642 AND p.seq = t.current_seq AND p.role IN ('buyer', 'Procedure-Buyer') LIMIT 200) q CROSS JOIN tenders t ON t.id = q.tid GROUP BY t.source, t.kind UNION ALL SELECT 1416875 AS org, b.role AS role, b.organization_id AS other, o.name AS oname, o.country AS ocountry, count(DISTINCT q.tid) AS tenders FROM (SELECT DISTINCT p.tender_id AS tid, p.seq AS sq FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1416875 AND p.seq = t.current_seq AND p.role IN ('buyer', 'Procedure-Buyer') LIMIT 200) q CROSS JOIN tender_version_parties b ON b.tender_id = q.tid AND b.seq = q.sq CROSS JOIN organizations o ON o.id = b.organization_id WHERE b.organization_id <> 1416875 GROUP BY b.role, b.organization_id UNION ALL SELECT 1416875 AS org, 'SOURCE' AS role, NULL AS other, t.source AS oname, t.kind AS ocountry, count(*) AS tenders FROM (SELECT DISTINCT p.tender_id AS tid, p.seq AS sq FROM tender_version_parties p CROSS JOIN tenders t ON t.id = p.tender_id WHERE p.organization_id = 1416875 AND p.seq = t.current_seq AND p.role IN ('buyer', 'Procedure-Buyer') LIMIT 200) q CROSS JOIN tenders t ON t.id = q.tid GROUP BY t.source, t.kind
